// RSS feed URLs — mirrors the app's .env RSS_FEEDS config
const feeds = [
  'https://techcrunch.com/category/artificial-intelligence/feed/',
  'https://feeds.arstechnica.com/arstechnica/technology-lab',
  'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml'
];

return feeds.map(url => ({ json: { feedUrl: url } }));

// Source name mapping — same as rssIngestion.js SOURCE_MAP
const SOURCE_MAP = {
  'techcrunch.com': 'TechCrunch',
  'arstechnica.com': 'Ars Technica',
  'theverge.com': 'The Verge',
  'technologyreview.com': 'MIT Technology Review',
  'venturebeat.com': 'VentureBeat'
};

function extractSourceName(url) {
  for (const [domain, name] of Object.entries(SOURCE_MAP)) {
    if (url.includes(domain)) return name;
  }
  try { return new URL(url).hostname; } catch { return 'Unknown'; }
}

function extractCategory(item) {
  if (item.categories) {
    const cats = typeof item.categories === 'string'
      ? item.categories.split(',')
      : Array.isArray(item.categories) ? item.categories : [];
    if (cats.length > 0) {
      const cat = typeof cats[0] === 'string' ? cats[0] : (cats[0].name || cats[0]._ || 'general');
      return cat.toLowerCase().trim();
    }
  }
  return 'ai';
}

function stripHtml(text) {
  if (!text) return '';
  return text.replace(/<[^>]*>/g, ' ').replace(/&[^;]+;/g, ' ').replace(/\s+/g, ' ').trim();
}

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const url = (data.link || data.guid || '').trim();
  if (!url) continue;

  const title = (data.title || 'Untitled').trim();
  const source = extractSourceName(url);
  const category = extractCategory(data);
  const publishedAt = data.isoDate || data.pubDate || data.date || new Date().toISOString();

  const content = stripHtml(
    data['content:encoded'] || data.content || data.contentSnippet || data.summary || ''
  );

  let summary = stripHtml(
    data.contentSnippet || data.summary || ''
  ).slice(0, 500);

  const needsSummary = (!summary || summary.length <= 50) && content && content.length >= 100;

  results.push({
    json: {
      title,
      url,
      source,
      published_at: publishedAt,
      category,
      summary: summary || null,
      content: content || null,
      needs_summary: needsSummary
    }
  });
}

return results;

