// Merge the LLM-generated summary back into the article item
const llmResponse = $json;
const article = $('Needs LLM Summary?').first().json;

const generatedSummary = llmResponse.choices?.[0]?.message?.content || article.summary;

return [{
  json: {
    ...article,
    summary: generatedSummary.trim(),
    needs_summary: false
  }
}];

const items = $input.all();
let inserted = 0;
let skipped = 0;
let errors = 0;

for (const item of items) {
  if (item.json.error) {
    errors++;
  } else if (item.json.id) {
    inserted++;
  } else {
    skipped++;
  }
}

return [{
  json: {
    message: `RSS Ingestion complete. Inserted: ${inserted}, Skipped (duplicates): ${skipped}, Errors: ${errors}`,
    inserted,
    skipped,
    errors,
    total: items.length,
    timestamp: new Date().toISOString()
  }
}];
